/* Software UP — interface com API autenticada ou demonstração local independente. */
(()=>{'use strict';
const $=s=>document.querySelector(s), L=window.UPLogic, backend=window.UPBackend, C=window.UPCharts, visualPreview=!!window.UPPreview;
let loading=!!backend;
const icon=(name,n=19)=>window.UP?UP.icon(name,n):'';
const money=(n,cents=true)=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:cents?2:0,maximumFractionDigits:cents?2:0});
const num=(n,d=1)=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const dateBR=s=>s?new Date(String(s).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const badge=(s,type='')=>`<span class="badge ${type}">${esc(s)}</span>`;
const sq=(i,cls='')=>`<span class="square-icon ${cls}">${icon(i)}</span>`;
const button=(label,action,cls='')=>`<button type="button" class="btn ${cls}" data-action="${esc(action)}">${label}</button>`;
const go=(label,page,cls='')=>`<button type="button" class="btn ${cls}" data-go="${esc(page)}">${label}${icon('arrow-right',16)}</button>`;
const empty=(title,desc,cta='',url='')=>`<div class="empty">${sq('file-text')}<h3>${title}</h3><p>${desc}</p>${url?go(cta,url,'primary'):''}</div>`;
const panel=(title,body,extra='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><h2 class="panel-title">${title}</h2>${extra}</div>${body}</section>`;
const head=(title,desc,extra='')=>`<header class="page-head"><div><div class="eyebrow">Software UP · Universo do Propósito</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div>${extra}</header>`;
const field=(label,name,val='',type='text',hint='',more='')=>`<div class="field"><label for="${esc(name)}">${label}</label><input id="${esc(name)}" name="${esc(name)}" type="${type}" ${type==='number'?((/\bmin=/.test(more)?'':'min="0" ')+(/\bstep=/.test(more)?'':'step="any" ')+'inputmode="decimal" lang="pt-BR"'):''} value="${esc(val)}" ${more}><span class="field-hint">${hint}</span></div>`;
const ta=(label,name,val='',hint='')=>`<div class="field"><label for="${esc(name)}">${label}</label><textarea id="${esc(name)}" name="${esc(name)}">${esc(val)}</textarea>${hint?`<span class="field-hint">${hint}</span>`:''}</div>`;
const select=(label,name,values,val='',hint='')=>`<div class="field"><label for="${esc(name)}">${label}</label><select id="${esc(name)}" name="${esc(name)}">${values.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===val?'selected':''}>${esc(t)}</option>`}).join('')}</select>${hint?`<span class="field-hint">${hint}</span>`:''}</div>`;
const kpi=(label,value,hint='',cls='')=>`<div class="kpi ${cls}"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><small>${hint}</small></div>`;
const RO=['Comunhão com Deus','Família','Saúde e energia','Propósito e clareza','Finanças pessoais','Negócio','Relacionamentos','Contribuição e serviço'];
const RA=['Vendas','Pessoas','Processos','Finanças'];
const REF={Vendas:'Público, problema, promessa, processo comercial, conversão e continuidade',Pessoas:'Papéis, competência, alinhamento, feedback, delegação e cultura',Processos:'Etapas críticas, responsáveis, padrões, prazos, documentação e melhoria',Finanças:'Caixa, custos, margem, retirada, dívida, reserva e critérios'};
const DIFFICULTIES=['conseguir clientes','dinheiro que não fecha','organização e equipe','uma decisão travada','não sei por onde começar'];
const FIN_VAR=[['tax','Impostos sobre vendas'],['fees','Taxas de cartão e plataformas'],['commission','Comissões'],['material','Mercadorias, materiais e insumos']];
const FIN_FIX=[['rent','Aluguel e contas'],['staff','Salários e encargos'],['systems','Sistemas e serviços'],['marketing','Marketing'],['other','Outros custos fixos']];
const CAT=['vendas','impostos','taxas','comissões','mercadoria','aluguel e contas','equipe','sistemas','marketing','outros','retirada'];
const KIT=[['ledger','Raio-X automático','Lançamentos, contas a pagar, dívidas e exportação CSV.','wallet'],['scripts','Roteiros de prospecção','Mensagens de prospecção e indicação para copiar ou enviar.','message-circle'],['offers','Ofertas modelo','Ofertas em Uma Página editáveis, por tipo de negócio.','file-text'],['plan','Plano de 90 Dias','Plano editável e check-in semanal para acompanhar a execução.','calendar'],['procedures','Kit de transferência','Procedimentos, checklist e roteiro de delegação.','clipboard-check']];
const SCRIPT_EXAMPLES=[{id:1,title:'Pedir indicação',text:'Olá, {nome}! Espero que esteja bem. Se conhecer alguém que precise de {serviço}, ficarei feliz em ajudar. Posso contar com sua indicação?'},{id:2,title:'Agradecer indicação',text:'Oi, {nome}! Obrigado por lembrar do meu trabalho e indicar meu {serviço}. Fico muito grato pela confiança.'},{id:3,title:'Reativar cliente antigo',text:'Olá, {nome}! Passando para saber como você está e se posso ajudar novamente com {serviço}. Estou à disposição.'},{id:4,title:'Retomar orçamento',text:'Olá, {nome}! Gostaria de saber se ficou alguma dúvida sobre o orçamento de {serviço}. Podemos conversar?'},{id:5,title:'Primeira abordagem',text:'Olá, {nome}! Meu trabalho é com {serviço}. Gostaria de entender sua necessidade e como posso ser útil.'}];
const OFFERS=['Prestador de serviço','Comércio','Autônomo','Profissional liberal'];
const TERMS='Demonstração: nesta versão, os dados informados permanecem neste navegador. Antes do lançamento, precisamos de termos aprovados, armazenamento seguro e aceite versionado.';
const fresh=()=>({user:{name:'João Silva',email:''},signed:false,screen:'login',codeEmail:'',consent:false,entitlements:{front:true,essencial:false,kit:false},diagnosticDraft:{roda:{},radar:{},gargalo:'',dificuldade:'',dificuldadeTexto:'',perfil:{}},diagStep:0,diagnostics:[],financeDraft:{revenue:'',sales:'',variable:{},fixed:{},owner:'',house:'',separate:'as_vezes',debts:[],reserveCompany:'',reservePersonal:''},finStep:0,finances:[],kitTransactions:[],kitBills:[],personalOffers:[],plan:{result:'',decision1:'',decision2:'',decision3:'',decision4:'',phase1:'',phase2:'',phase3:'',reminder:'segunda-feira'},checkins:[],procedures:[],admin:{productIds:{front:'',essencial:'',kit:''},kitLink:''},webhookEvents:[],messageTemplates:SCRIPT_EXAMPLES,financeViewMonth:today().slice(0,7),kitTab:'ledger',adminTab:'overview',historyTab:'diag',contentSub:'',selectedScript:'1',notes:[]});
let state;try{state=Object.assign(fresh(),JSON.parse(localStorage.getItem('up-demo-v2')||'{}'));}catch(e){state=fresh();}
if(backend)state=fresh();
if(visualPreview){state=Object.assign(fresh(),window.UPPreview(L));try{state=Object.assign(state,JSON.parse(localStorage.getItem('up-preview-v1')||'{}'));}catch{}state.signed=true;}
function normalizeState(){const defaults=fresh();for(const key of ['kitTransactions','kitBills','personalOffers','procedures','checkins']){if(!Array.isArray(state[key]))state[key]=[];for(const row of state[key])if(!row.id)row.id=newId();}state.plan={...defaults.plan,...state.plan};state.diagnosticDraft={...defaults.diagnosticDraft,...state.diagnosticDraft};state.financeDraft={...defaults.financeDraft,...state.financeDraft};}
normalizeState();
let active=location.hash.replace('#/','')|| (state.signed?'dashboard':'login');let toastTimer;
function save(){if(visualPreview){try{localStorage.setItem('up-preview-v1',JSON.stringify(state));}catch{flash('Não foi possível salvar neste navegador. Exporte seus dados antes de sair.');}return;}if(backend){if(state.signed&&!loading)backend.save(state);return;}try{localStorage.setItem('up-demo-v2',JSON.stringify(state));}catch(e){console.warn('Storage indisponível',e);}}
function flash(s){if(backend)s=s.replace(/neste navegador|no navegador|localmente/g,'— aguardando sincronização');$('#toast').innerHTML=`<div class="toast-inner">${esc(s)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').innerHTML='',3200);}
function navigate(page){active=page;location.hash='/'+page;window.scrollTo({top:0,behavior:'instant'});render();}
window.addEventListener('hashchange',()=>{active=location.hash.replace('#/','')||'dashboard';render();});
const has=key=>key==='front'?!!state.entitlements.front: key==='kit'?!!state.entitlements.kit:!!(state.entitlements.kit||state.entitlements.essencial);
const permitted=key=>!['kit','essencial'].includes(key)||has(key);
function navItems(){return [['dashboard','Visão geral','home'],['diagnostic','Diagnóstico UP','clipboard-check'],['finance','Raio-X financeiro','chart-bar'],['kit-essential','Kit Essencial','book-open'],['kit','Kit UP Completo','crown'],['history','Histórico','history'],['profile','Minha conta','user'],['support','Ajuda e suporte','circle-help'],['admin','Admin (prévia)','sliders-horizontal']].filter(item=>!backend||item[0]!=='admin');}
function appShell(content){
 const navActive=({'diagnostic-result':'diagnostic','finance-result':'finance',ledger:'kit-essential',scripts:'kit-essential',offers:'kit',plan:'kit',procedures:'kit'})[active]||active;
 const mobileItems=[['dashboard','Início','home'],['diagnostic','Diagnóstico','clipboard-check'],['finance','Raio-X','chart-bar'],['kit','Kit','crown'],['profile','Conta','user']];
 const current=navItems().find(a=>a[0]===active)?.[1]||({'diagnostic-result':'Meu diagnóstico','finance-result':'Meu Raio-X',ledger:'Raio-X automático',scripts:'Roteiros de prospecção',offers:'Ofertas modelo',plan:'Plano de 90 dias',procedures:'Kit de transferência'})[active]||'Software UP';
 const initials=esc(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase());
 const searchItems=[...navItems(),...KIT.map(([route,title,,ic])=>[route,title,ic])];
 const pendingBills=has('essencial')?state.kitBills.filter(b=>!b.paid&&b.due&&new Date(b.due+'T12:00:00')<=new Date(Date.now()+7*86400000)):[];
 const finance=state.finances.at(-1)?.result;
 const notices=[...(pendingBills.length?[{title:pendingBills.length+' conta(s) com vencimento próximo',text:'Confira datas e pagamentos no seu controle mensal.',route:'ledger',ic:'calendar'}]:[]),...(finance&&finance.afterDebt<0?[{title:'Seu financeiro precisa de atenção',text:'Veja as prioridades do seu último Raio-X.',route:'finance-result',ic:'wallet'}]:[])];
 return `<div class="app-body"><div class="shell"><aside class="side" aria-label="Menu lateral"><div class="sidebar-top"><button type="button" class="sidebar-brand" data-go="dashboard" aria-label="UP Software · Visão geral"><img class="side-symbol" src="design-system/assets/logos/up-simbolo-branco.png" alt="UP"><span>SOFTWARE</span></button><button type="button" class="sidebar-toggle" data-action="toggle-sidebar" aria-controls="up-sidebar-nav" aria-expanded="true" aria-label="Recolher menu">${icon('chevron-left',16)}</button></div><nav id="up-sidebar-nav" aria-label="Navegação principal"><div class="nav-section nav-section-primary">Principal</div>${navItems().map(([page,title,ico])=>`${page==='profile'?'<div class="nav-section">Minha conta</div>':''}<button type="button" class="nav-link ${navActive===page?'active':''} ${page.startsWith('kit')?'nav-premium':''}" data-go="${page}" aria-label="${esc(title)}" title="${esc(title)}" ${navActive===page?'aria-current="page"':''}><span class="ic">${icon(ico)}</span><span class="nav-label">${esc(title)}</span>${page==='kit'&&!has('essencial')?`<span class="trailing">${icon('lock',14)}</span>`:''}</button>`).join('')}<button type="button" class="nav-link nav-logout" data-action="logout" aria-label="Sair" title="Sair"><span class="ic">${icon('log-out')}</span><span class="nav-label">Sair</span></button></nav><div class="nav-spacer"></div><button class="sidebar-promo" data-go="kit" aria-label="Explorar Kit UP Completo" title="Explorar Kit UP Completo">${icon('crown',24)}<span class="promo-copy"><b>Kit UP Completo</b><small>Clareza para colocar em prática.</small><span>Explorar ferramentas ${icon('arrow-right',14)}</span></span></button></aside><button class="menu-backdrop" data-action="close-sidebar" aria-label="Fechar menu" tabindex="-1"></button><div class="main"><header class="topbar"><div class="tool-search" role="search"><label for="tool-search" class="screen-reader">Buscar ferramentas</label>${icon('search',18)}<input id="tool-search" data-tool-search autocomplete="off" placeholder="Buscar ferramentas ou resultados…" aria-controls="tool-search-results" aria-expanded="false"><span class="search-key">↓</span><div id="tool-search-results" class="header-popover" hidden>${searchItems.map(([route,title,ic])=>`<button type="button" data-go="${route}">${icon(ic,18)}<span>${esc(title)}</span>${icon('arrow-up-right',14)}</button>`).join('')}<p class="search-empty" hidden>Nenhuma ferramenta encontrada.</p></div></div><div class="header-actions"><button class="header-icon" data-go="support" aria-label="Ajuda e suporte" title="Ajuda e suporte">${icon('mail',18)}</button><div class="notification-wrap"><button class="header-icon" data-action="toggle-notifications" aria-label="Notificações${notices.length?', '+notices.length+' aviso(s)':''}" aria-expanded="false" aria-controls="notification-panel">${icon('bell',18)}${notices.length?'<i class="unread-dot"></i>':''}</button><section id="notification-panel" class="header-popover" aria-label="Notificações" hidden><div class="popover-title">Notificações ${notices.length?badge(notices.length+' aviso(s)','orange'):''}</div>${notices.length?notices.map(n=>`<button data-go="${n.route}">${sq(n.ic,'orange')}<span><b>${esc(n.title)}</b><small>${esc(n.text)}</small></span></button>`).join(''):'<p class="notification-empty">Nenhum aviso por enquanto.</p>'}</section></div><button class="user-pill" data-go="profile"><span class="avatar">${initials}</span><span class="user-meta"><b>${esc(state.user.name)}</b><small>${visualPreview?'Prévia visual':'Aluno UP'}</small></span>${icon('chevron-down',16)}</button></div></header><header class="mobile-top"><button class="mobile-menu-toggle" data-action="toggle-sidebar" aria-controls="up-sidebar-nav" aria-expanded="false" aria-label="Abrir menu">${icon('menu',22)}</button><span class="mobile-page-name">${esc(current)}</span><button class="avatar mobile-avatar" data-go="profile" aria-label="Minha conta">${initials}</button></header><main class="workspace" id="main-content"><div class="demo-strip"><span class="demotag">${visualPreview?'PRÉVIA VISUAL':'DEMO'}</span><span>${visualPreview?'Dados ilustrativos · explore as ferramentas com tranquilidade.':'Demonstração · Seus dados ficam neste navegador.'}</span>${visualPreview?'<a href="/">Voltar ao login '+icon('arrow-up-right',14)+'</a>':''}</div>${content}</main></div></div><nav class="bottom-nav" aria-label="Navegação mobile">${mobileItems.map(([p,t,i])=>`<button data-go="${p}" class="${(p===navActive||(p==='kit'&&navActive==='kit-essential'))?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav></div>`;
}

function authLayout(content,verify){return `<div class="auth-shell"><aside class="auth-side"><a class="auth-brand" href="/"><img src="design-system/assets/logos/up-logo-branco.png" alt="Universo do Propósito"></a><div class="auth-art" aria-hidden="true"><span></span><span></span><span></span></div><div class="auth-intro"><div class="auth-kicker">UNIVERSO DO PROPÓSITO</div><h1>Seu próximo passo <br>começa com <span>clareza.</span></h1><p>Um olhar para o seu negócio. <br>Um caminho para o seu propósito.</p></div><div class="auth-trust"><span>${icon('lock',16)} Acesso seguro</span><span>${icon('mail',16)} Código por e-mail</span><span>${icon('check',16)} Sem senha</span></div></aside><main class="auth-right"><div class="auth-topline"><span>Software UP</span><span>${icon('circle-help',16)} Plataforma do aluno</span></div><div class="auth-card"><div class="auth-step">${verify?'02 / VERIFICAÇÃO':'01 / BEM-VINDO'}</div><div class="auth-symbol square-icon ${verify?'orange':''}">${icon(verify?'lock':'mail',24)}</div>${content}</div><footer class="auth-footer"><span>© ${new Date().getFullYear()} Universo do Propósito</span><span>Clareza. Estrutura. Evolução.</span></footer></main></div>`;}
function codeFields(){return `<label class="auth-label" id="code-label">Código de acesso</label><div class="code-fields" role="group" aria-labelledby="code-label">${[0,1,2,3,4,5].map(i=>`<input name="digit${i}" inputmode="numeric" pattern="[0-9]" maxlength="1" required autocomplete="${i===0?'one-time-code':'off'}" aria-label="Dígito ${i+1}">`).join('')}</div>`;}
function integratedAuth(){const verify=active==='code';return authLayout(verify?`<h2>Verifique seu e-mail</h2><p>Se houver uma conta para <b>${esc(state.codeEmail)}</b>, você receberá um código de seis dígitos. Ele vale por dez minutos.</p><form id="verify-form">${codeFields()}<button class="btn primary full" type="submit">Entrar na plataforma ${icon('arrow-right',16)}</button></form><div class="auth-back">${go('Usar outro e-mail','login','ghost')}</div>`:`<h2>Acesse sua conta</h2><p>Use o mesmo e-mail da sua compra na Kiwify.<br>Vamos enviar um código para você entrar.</p><form id="login-form">${field('Seu e-mail','email',state.codeEmail,'email','','required autocomplete="email" placeholder="voce@empresa.com.br"')}<button class="btn primary full" type="submit">Enviar código ${icon('arrow-right',16)}</button></form><div class="auth-caption">${icon('lock',14)} Seu acesso é pessoal e protegido.</div><a class="auth-preview-link" href="app/preview.html">Explorar a interface ${icon('arrow-up-right',14)}</a>`,verify);}
function integratedProfile(){const tab=state.profileTab||'data';let body='';if(tab==='data')body=`<form id="profile-form" class="interactive-form"><div class="form-grid">${field('Nome completo','name',state.user.name,'text','','required minlength="2" maxlength="120"')}${field('E-mail de acesso','email',state.user.email,'email',backend?'O e-mail de acesso é o mesmo da compra.':'E-mail usado nesta prévia.','required '+(backend?'readonly':''))}</div><div class="form-actions"><button class="btn primary" type="submit">Salvar meu perfil</button></div></form>`;if(tab==='security')body=`<div class="readout"><h3>Acesso por código</h3><p>Seu acesso usa um código enviado por e-mail. Você pode encerrar sua sessão neste dispositivo.</p></div><div class="form-actions">${button('Sair da conta','logout')}</div>`;if(tab==='plan')body=`<div class="profile-plan">${sq('crown','orange')}<div><small>Seu plano atual</small><h3>${has('kit')?'Kit UP Completo':has('essencial')?'Kit Essencial':'Diagnóstico e Raio-X'}</h3></div></div><div class="form-actions">${go('Ver minhas ferramentas','kit','primary')}</div>`;return `${head('Meu perfil','Seus dados, seu acesso e suas ferramentas em um só lugar.')}<div class="profile-layout"><section class="panel profile-summary"><span class="avatar profile-avatar">${esc(state.user.name.slice(0,1))}</span><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p>${badge('Aluno UP','blue')}<div class="divider"></div>${[['data','Dados pessoais','user'],['security','Segurança e acesso','lock'],['plan','Meu plano','crown']].map(([key,label,ic])=>`<button class="profile-section ${tab===key?'selected':''}" data-action="profile-tab" data-tab="${key}" aria-pressed="${tab===key}">${icon(ic)}${label}</button>`).join('')}</section>${panel(({data:'Dados pessoais',security:'Segurança e acesso',plan:'Meu plano'})[tab],body)}</div>`;}
function authPage(){if(backend)return integratedAuth();const verify=active==='code';return authLayout(verify?`<h2>Verifique seu e-mail</h2><p>Na demonstração, use o código <b>123456</b> para conhecer a plataforma.</p><form id="verify-form">${codeFields()}<button class="btn primary full" type="submit">Entrar na plataforma ${icon('arrow-right',16)}</button></form><div class="auth-back">${go('Usar outro e-mail','login','ghost')}</div>`:`<h2>Acesse sua conta</h2><p>Use o mesmo e-mail da sua compra na Kiwify.</p><form id="login-form">${field('Seu e-mail','email',state.user.email,'email','','required placeholder="voce@empresa.com.br"')}<button type="submit" class="btn primary full">Enviar código ${icon('arrow-right',16)}</button></form><div class="auth-demo"><p>Explore a interface com dados de demonstração.</p>${button('Entrar na demonstração sem código','demo-enter','full')}</div>`,verify);}

function metricStatus(kind){return kind==='verde'?'good':kind==='amarelo'?'warn':kind==='vermelho'?'bad':'';}

const AREA_ICONS={Vendas:'trending-up',Pessoas:'users',Processos:'sliders-horizontal',Finanças:'wallet'};
const rodaShort=['Comunhão|com Deus','Família','Saúde e|energia','Propósito','Finanças|pessoais','Negócio','Relaciona-|mentos','Contribuição'];
function radarData(result){return RO.map((name,i)=>({name,short:rodaShort[i],value:result.roda[name]?.score||0}));}
function financeRows(){return state.finances.slice().sort((a,b)=>a.month.localeCompare(b.month)).slice(-6).map(x=>({label:new Date(x.month+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.',''),revenue:x.result.revenue,expenses:x.result.revenue-x.result.operating,profit:x.result.operating}));}
function areaList(dr){return `<div class="score-list">${RA.map(k=>`<div class="score-row">${sq(AREA_ICONS[k],dr.gargalo===k?'orange':'')}<span>${esc(k)}${dr.gargalo===k?badge('Gargalo','orange'):''}</span><b>${num(dr.radar[k].score,0)}<small>/10</small></b></div>`).join('')}</div>`;}
function dashboard(){
 const diag=state.diagnostics.at(-1),snap=state.finances.at(-1),dr=diag?.result,fr=snap?.result;
 const previous=state.diagnostics.at(-2)?.result;
 const delta=previous&&dr?dr.mediaRadar-previous.mediaRadar:null;
 const month=snap?new Date(snap.month+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long'}):'';
 const priority=fr?fr.traffic.separate!=='verde'?['Separe as contas da casa e da empresa','Defina um dia fixo e um valor de retirada.']:fr.afterDebt<0?['Revise seus custos e preços','Entenda o que precisa mudar para o dinheiro fechar.']:['Prepare seu próximo passo','Acompanhe as prioridades do seu último Raio-X.']:dr?['Olhe para '+dr.gargalo,'Escolha uma ação para melhorar essa área do seu negócio.']:['Comece pelo seu diagnóstico','Um olhar para a vida e para a estrutura do seu negócio.'];
 const plans=['decision1','decision2','decision3','decision4'].map(key=>state.plan[key]).filter(Boolean);
 const metric=(label,value,meta,route,primary=false)=>`<button class="overview-metric ${primary?'featured':''}" data-go="${route}"><span class="metric-heading">${label}<span class="metric-arrow">${icon('arrow-up-right',16)}</span></span><strong>${value}</strong><span class="metric-meta">${meta}</span></button>`;
 return `<header class="overview-heading"><div><h1>Visão geral</h1><p>Clareza sobre seu negócio. Direção para o próximo passo.</p></div><div class="btn-row">${go('Novo diagnóstico','diagnostic','primary')}${go('Ver histórico','history','secondary')}</div></header><div class="overview-metrics">${metric('Média do Radar',dr?num(dr.mediaRadar):'—',dr?delta!==null?icon('trending-up',14)+' '+(delta>0?'+':'')+num(delta)+' ponto(s) desde o anterior':'Seu último diagnóstico':'Conheça seu ponto de partida',diag?'diagnostic-result':'diagnostic',true)}${metric('Faturamento mensal',fr?money(fr.revenue,false):'—',snap?'Referência: '+esc(month):'Preencha seu primeiro Raio-X',snap?'finance-result':'finance')}${metric('Resultado operacional',fr?money(fr.operating,false):'—',fr?`<span class="metric-accent">${num(fr.revenue?fr.operating/fr.revenue*100:0)}%</span> do faturamento`:'Seus números em perspectiva',snap?'finance-result':'finance')}${metric('Ponto de equilíbrio',fr?fr.breakEven===null?'Não aplicável':money(fr.breakEven,false):'—',fr&&fr.breakEven!==null?fr.breakEven>fr.revenue?`<span class="metric-accent">Ajuste de ${money(fr.breakEven-fr.revenue,false)}</span> para empatar`:'Seus custos cobertos pelas vendas':'Quanto você precisa faturar',snap?'finance-result':'finance')}</div><div class="overview-grid"><section class="panel overview-finance"><div class="panel-head"><div><h2 class="panel-title">Evolução financeira</h2><p class="panel-sub">${state.finances.length?'Últimos '+Math.min(state.finances.length,6)+' meses':'Seu acompanhamento mensal'}</p></div></div>${state.finances.length?C.plot(financeRows(),{bars:true,profit:false}):empty('Seus números ganham clareza aqui','Registre seu primeiro Raio-X para acompanhar a evolução.','Fazer Raio-X','finance')}</section><section class="panel overview-priority">${badge('Prioridade','orange')}<span class="priority-label">Sua próxima ação</span><h2>${esc(priority[0])}</h2><p>${esc(priority[1])}</p>${go('Ver orientação',snap?'finance-result':diag?'diagnostic-result':'diagnostic','primary full')}</section><section class="panel overview-tools"><div class="panel-head"><h2 class="panel-title">Ferramentas do Kit</h2>${go('Abrir','kit','small')}</div><div class="overview-tool-list">${KIT.map(([route,title,desc,ic],i)=>{const unlocked=i<2?has('essencial'):has('kit');return `<button data-go="${unlocked?route:'kit'}" title="${esc(desc)}">${sq(ic,i%2?'orange':'')}<span><b>${title}</b><small>${['Controle de lançamentos','Converse com seus clientes','Sua oferta em uma página','Prioridades e execução','Processos para delegar'][i]}</small></span>${unlocked?'<i class="tool-access" aria-label="Liberado"></i>':icon('lock',14)}${icon('chevron-right',14)}</button>`;}).join('')}</div></section><section class="panel overview-plan"><div class="panel-head"><h2 class="panel-title">Meu plano de 90 dias</h2>${go('Ver plano','plan','small')}</div>${plans.length?`<div class="overview-plan-list">${plans.map((text,i)=>`<button data-go="plan"><span class="plan-checkbox">${icon('file-text',16)}</span><span class="plan-step-text">${esc(text)}</span>${badge(i===0?'Prioridade':'Planejado',i===0?'orange':'blue')}</button>`).join('')}</div>`:empty('Clareza para colocar em prática','Organize as decisões que vão guiar os próximos meses.','Conhecer o plano',has('kit')?'plan':'kit')}</section><section class="panel overview-wheel"><div class="panel-head"><h2 class="panel-title">Roda da Plenitude</h2>${diag?go('Ver notas','diagnostic-result','link'):''}</div>${dr?`${C.gauge(dr.mediaRoda)}<p class="wheel-care">${icon('info',14)} Um olhar de cuidado para ${esc(dr.cuidados.join(', '))}.</p>`:empty('Vida e negócio caminham juntos','Descubra as oito dimensões da sua Roda.','Fazer diagnóstico','diagnostic')}</section><section class="overview-focus">${icon('crown',22)}<small>Seu foco da semana</small><h2>Organizar<br>para crescer.</h2><p>Um passo de cada vez.</p>${go('Ver ferramentas','kit','orange')}</section></div>`;
}

function diagnosticPage(){let s=state.diagStep;const d=state.diagnosticDraft;const latest=state.diagnostics.at(-1);
 const progress=`<div class="stepper">${[0,1,2].map(i=>`<div class="one ${i<=s?'on':''}"></div>`).join('')}</div>`;
 const scoreCard=(name,group,hint='')=>{const v=d[group][name]||{};return `<div class="question-card ${v.score!==undefined?'answered':''}"><div class="row-between" style="margin-bottom:7px"><div class="question-title">${esc(name)}</div><b style="color:#0031E8">${v.score!==undefined?num(v.score,0)+'/10':'Não respondido'}</b></div>${hint?`<p class="muted-label" style="margin-bottom:12px">${esc(hint)}</p>`:''}<div class="rating-strip" role="group" aria-label="Nota de ${esc(name)}">${Array.from({length:11},(_,i)=>`<button type="button" data-score-group="${group}" data-score-name="${esc(name)}" data-score-value="${i}" class="rating-btn ${String(v.score)===String(i)?'on':''}" aria-pressed="${String(v.score)===String(i)}">${i}</button>`).join('')}</div><details class="evidence-field"><summary>Adicionar evidência (opcional)</summary><div class="field"><label>O que justifica esta nota?</label><textarea data-evidence-group="${group}" data-evidence-name="${esc(name)}" placeholder="O que justifica esta nota?">${esc(v.evidence)}</textarea></div></details></div>`;};
 let body='';if(s===0)body=`<div class="notice-box">${icon('info')}<span>Olhe para o seu momento atual. Dê uma nota de 0 a 10 para cada dimensão e registre o que justifica sua escolha.</span></div><div class="section-label">8 dimensões da Roda da Plenitude</div><div class="layout-grid">${RO.map(n=>`<div class="c6">${scoreCard(n,'roda')}</div>`).join('')}</div>`;
 if(s===1)body=`<div class="notice-box">${icon('info')}<span>Agora avalie a estrutura do seu negócio nas quatro áreas. Cada nota deve refletir sua situação atual.</span></div><div class="section-label">Radar da Estrutura</div><div class="layout-grid">${RA.map(n=>`<div class="c6">${scoreCard(n,'radar',REF[n])}</div>`).join('')}</div>`;
 if(s===2){let scores=RA.map(n=>({n,v:Number(d.radar[n]?.score??10)})),low=Math.min(...scores.map(x=>x.v)),tie=scores.filter(x=>x.v===low).map(x=>x.n);body=`<div class="notice-box"><span>${icon('info')} A menor nota do Radar aponta para <b>${esc(tie.join(', '))}</b>. Confirme qual área, se resolvida, liberaria mais capacidade no negócio.</span></div><form id="diagnostic-profile" class="form-column" style="margin-top:20px"><div class="form-grid">${select('Gargalo principal','gargalo',tie,d.gargalo||tie[0])}${select('Maior dificuldade','dificuldade',DIFFICULTIES,d.dificuldade)}${select('Tipo de negócio','business',['Serviço','Comércio','Autônomo','Profissional liberal','Outro'],d.perfil.business)}${field('Tempo de atividade','age',d.perfil.age,'text','Ex.: 3 anos')}${select('Faixa de faturamento mensal','band',['Até R$ 5 mil','R$ 5 mil a R$ 20 mil','R$ 20 mil a R$ 50 mil','R$ 50 mil a R$ 100 mil','Acima de R$ 100 mil','Prefiro não informar'],d.perfil.band)}${field('Tamanho da equipe','team',d.perfil.team,'number','Inclua você se atua na operação')}${ta('Descreva sua maior dificuldade (opcional)','dificuldadeTexto',d.dificuldadeTexto)}</div><div class="sticky-actions">${button('Voltar','diag-back') }<button class="btn primary" type="submit">Concluir Diagnóstico ${icon('arrow-right',16)}</button></div></form>`;}
 return `${head('Diagnóstico UP','Uma visão sobre sua vida e a estrutura do seu negócio. Tempo estimado: 10 a 15 minutos.',latest?go('Último resultado','diagnostic-result',''):'')}<div class="layout-grid"><div class="c8">${panel(`<span style="font-weight:700">Etapa ${s+1} de 3</span> · ${['Roda da Plenitude','Radar da Estrutura','Gargalo e perfil'][s]}`,`${progress}${body}${s!==2?`<div class="sticky-actions">${s===0?`<span class="muted-label">Responda todas as notas para avançar.</span>`:button('Voltar','diag-back')} ${button('Próxima etapa','diag-next','primary')}</div>`:''}`)}</div><div class="c4">${panel('Como funciona',`<div class="link-list">${[['1','Roda da Plenitude','Oito dimensões pessoais'],['2','Radar da Estrutura','Vendas, Pessoas, Processos e Finanças'],['3','Resultado e direcionamento','Gargalo, prioridade e leitura das regras']].map(([i,t,p])=>`<div class="button-card"><span class="square-icon">${i}</span><span class="list-content"><b>${t}</b><p>${p}</p></span></div>`).join('')}</div><p class="subtle-footnote">Este diagnóstico é uma ferramenta de reflexão e organização. Não substitui orientação contábil, jurídica ou de saúde.</p>`)}</div></div>`;
}
function diagnosticResult(){const item=state.diagnostics.find(x=>String(x.id)===String(state.selectedDiagnostic))||state.diagnostics.at(-1);if(!item)return `${head('Seu diagnóstico','Conheça sua vida e a estrutura do seu negócio.')}${panel('Comece pelo Diagnóstico',empty('Nenhum resultado ainda','Responda à Roda da Plenitude e ao Radar da Estrutura.','Começar','diagnostic'))}`;
 const v=item.result;
 return `${head('Seu diagnóstico','Clareza sobre o seu momento. Direção para o seu próximo passo.',button('Imprimir relatório','print'))}<div class="diagnostic-overview"><section class="panel"><div class="panel-head"><h2 class="panel-title">Roda da Plenitude</h2>${badge('Vida em equilíbrio','blue')}</div>${C.radar(radarData(v))}<div class="wheel-summary"><div><small>Média da Roda</small><strong>${num(v.mediaRoda)}<span>/10</span></strong></div><div>${sq('info','orange')}<span><small>Um olhar de cuidado para</small><b>${esc(v.cuidados.join(', '))}</b></span></div></div><details class="result-details"><summary>Ver todas as notas ${icon('chevron-down',16)}</summary><div class="layout-grid roda-detail">${RO.map(x=>`<div class="c6"><div class="row-between"><span>${esc(x)}</span><b>${num(v.roda[x].score,0)}/10</b></div><div class="progress-track"><span style="width:${v.roda[x].score*10}%"></span></div></div>`).join('')}</div></details></section><div><section class="panel"><div class="panel-head"><h2 class="panel-title">Radar da Estrutura</h2>${badge('Seu negócio','blue')}</div><div class="score-container">${C.ring(v.mediaRadar,'Média Radar')}${areaList(v)}</div></section><section class="panel diagnosis-reading"><div class="panel-head"><h2 class="panel-title">O que pede sua atenção</h2>${sq('pen-line','orange')}</div><h3>Comece por ${esc(v.gargalo)}.</h3><p>Essa é a área com menor nota no seu Radar. Ao organizar esse ponto, você cria uma base melhor para avançar nas outras áreas.</p><div class="readout"><h3>Seu próximo passo</h3><p>${v.gargalo==='Finanças'?'Complete o Raio-X financeiro. Entenda seus custos e o que precisa mudar para o dinheiro fechar.':'Revise as aulas sobre '+esc(v.gargalo)+' na Kiwify e escolha uma ação para colocar em prática nesta semana.'}</p></div>${go('Continuar para o Raio-X','finance','primary full')}</section></div></div><div class="result-bottom"><p>Este diagnóstico é uma ferramenta de reflexão e organização. Não substitui orientação profissional contábil, jurídica ou de saúde.</p>${go('Refazer diagnóstico','diagnostic','link')}</div>`;
}

function financePreviewHtml(){const result=L.finance(state.financeDraft);return `<div class="live-calculation"><span>${badge('Prévia em tempo real','blue')}</span><div><span>Faturamento informado</span><b>${money(result.revenue)}</b></div><div><span>Custos variáveis</span><b>${money(result.cv)}</b></div><div><span>Custos fixos</span><b>${money(result.fixed)}</b></div><div><span>Sobra após dívidas</span><b class="${result.afterDebt<0?'negative-number':''}">${money(result.afterDebt)}</b></div><p>O resultado acompanha os campos preenchidos. Conclua as etapas para salvar a análise.</p></div>`;}
function updateFinancePreview(){const el=$('#finance-live-summary');if(el)el.innerHTML=financePreviewHtml();}
function updateDebtPreview(){const form=document.querySelector('#sim-debt');if(!form)return;const o=formData(form);if(!(Number(o.balance)>0)||!(Number(o.payment)>0)||Number(o.rate)<0||Number(o.extra)<0)return;const months=L.simulateDebt(o.balance,o.rate,o.payment,o.extra);$('#sim-output').innerHTML=`<div class="simulation-result" role="status">${months===null?'<h3>Essa parcela não cobre os juros.</h3><p>Aumente o pagamento mensal ou reduza os juros para encontrar um prazo de quitação.</p>':`<span>Prazo estimado para quitar</span><strong>${months}<small> mês(es)</small></strong><p>Pagamento mensal de ${money(Number(o.payment)+Number(o.extra))}, sem novas compras.</p>`}</div>`;}
function financePage(){const f=state.financeDraft,s=state.finStep,existing=state.finances.length;const names=['Entradas','Custos por venda','Custos fixos','Dono e casa','Dívidas','Reservas'];let main='';
 const financeNames={'Faturamento médio mensal (R$)':'revenue','Número de vendas por mês':'sales','Retirada mensal do dono (R$)':'owner','Custo mensal da casa (R$)':'house','Dinheiro disponível da empresa (R$)':'reserveCompany','Reserva pessoal (R$)':'reservePersonal'};
 const valInput=(label,v,hint='')=>field(label,financeNames[label],v,'number',hint);
 if(s===0)main=`<div class="form-grid">${valInput('Faturamento médio mensal (R$)',f.revenue,'Média dos últimos 3 meses')}${valInput('Número de vendas por mês',f.sales,'Usado para calcular o ticket médio')}</div>`;
 if(s===1)main=`<div class="form-grid">${FIN_VAR.map(([k,label])=>`<div class="field"><label>${label}</label><div class="row-between" style="gap:8px"><input aria-label="${label} valor" type="number" min="0" step="any" data-fv="${k}" value="${esc(f.variable[k]?.value??'')}" placeholder="0"><select aria-label="Unidade para ${label}" data-fu="${k}" style="max-width:95px"><option value="currency" ${f.variable[k]?.unit!=='percent'?'selected':''}>R$</option><option value="percent" ${f.variable[k]?.unit==='percent'?'selected':''}>%</option></select></div><span class="field-hint">B · Informe em reais ou como porcentagem do faturamento</span></div>`).join('')}</div>`;
 if(s===2)main=`<div class="form-grid">${FIN_FIX.map(([k,label])=>field(label,`fixed_${k}`,f.fixed[k],'number','C · Custo fixo mensal em R$')).join('')}</div>`;
 if(s===3)main=`<div class="form-grid">${valInput('Retirada mensal do dono (R$)',f.owner,'Pró-labore e retiradas')}${valInput('Custo mensal da casa (R$)',f.house,'Despesas pessoais')}${select('As contas de casa e empresa são separadas?','separate',[['sim','Sim'],['as_vezes','Às vezes'],['nao','Não']],f.separate)}</div>`;
 if(s===4)main=`<div class="notice-box">${icon('info')} <span>Cadastre cada dívida. Informe juros em percentual ao mês (por exemplo, 2 para 2%). Dívidas pessoais são separadas das empresariais.</span></div><div class="section-label">Dívidas cadastradas</div>${f.debts.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Credor</th><th>Tipo</th><th>Saldo</th><th>Parcela</th><th>Juros</th><th>Situação</th><th></th></tr></thead><tbody>${f.debts.map((d,i)=>`<tr><td>${esc(d.creditor)}</td><td>${esc(d.scope)}</td><td>${money(d.balance)}</td><td>${money(d.payment)}</td><td>${num(d.rate)}%</td><td>${d.overdue?badge('Atrasada','bad'):badge('Em dia','good')}</td><td><button class="btn small" data-action="remove-debt" data-index="${i}">${icon('x',14)}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted-label">Nenhuma dívida cadastrada.</p>'}<form id="debt-form" style="margin-top:18px"><div class="form-grid four">${field('Credor','creditor','','text','','required')}${select('Tipo','scope',[['empresa','Empresa'],['pessoal','Pessoal']],'empresa')}${field('Saldo devedor (R$)','balance','','number')}${field('Parcela mensal (R$)','payment','','number')}${field('Juros (% a.m.)','rate','','number')}${select('Em atraso?','overdue',[['no','Não'],['yes','Sim']],'no')}</div><button class="btn" style="margin-top:12px" type="submit">${icon('plus')} Adicionar dívida</button></form>`;
 if(s===5)main=`<div class="form-grid">${valInput('Dinheiro disponível da empresa (R$)',f.reserveCompany,'Valor acessível hoje')}${valInput('Reserva pessoal (R$)',f.reservePersonal,'Separada da empresa')}${select('Mês de referência','month',[...Array(12)].map((_,i)=>{const dt=new Date();dt.setMonth(dt.getMonth()-i);return [dt.toISOString().slice(0,7),dt.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})]}),f.month||today().slice(0,7))}</div><label class="form-checkbox" style="margin-top:16px"><input type="checkbox" name="estimated" ${f.estimated?'checked':''}> Parte dos valores é estimada e será conferida depois.</label>`;
 return `${head('Raio-X financeiro','Entenda o que realmente sobra, seu ponto de equilíbrio, sua reserva e o peso das dívidas.',existing?go('Última análise','finance-result'):'')}<div class="layout-grid"><div class="c8">${panel(`Passo ${s+1} de 6 · ${names[s]}`,`<div class="stepper">${names.map((x,i)=>`<div class="one ${i<=s?'on':''}" title="${x}"></div>`).join('')}</div>${main}<div class="sticky-actions">${s===0?'<span class="muted-label">Use os valores médios dos últimos 3 meses.</span>':button('Voltar','fin-back')}${button(s===5?'Calcular meu Raio-X':'Continuar','fin-next','primary')}</div>`)}</div><div class="c4">${panel('Resumo em tempo real',`<div id="finance-live-summary">${financePreviewHtml()}</div><div class="divider"></div><div class="link-list">${[['chart-bar','Margem de contribuição','Quanto sobra das vendas'],['wallet','Ponto de equilíbrio','Faturamento necessário para empatar'],['history','Meses de reserva','Autonomia sem vender'],['clipboard-check','Primeiras ações','Até três orientações por prioridade']].map(([ic,t,s])=>`<div class="button-card">${sq(ic)}<span class="list-content"><b>${t}</b><p>${s}</p></span></div>`).join('')}</div><p class="subtle-footnote">Esta ferramenta organiza informações para sua decisão. Não é recomendação financeira e não substitui seu contador.</p>`)}</div></div>`;
}
function financeResult(){const o=state.finances.find(x=>String(x.id)===String(state.selectedFinance))||state.finances.at(-1);if(!o)return `${head('Seu Raio-X financeiro','Seus números ganham clareza aqui.')}${panel('Sem dados',empty('Faça seu primeiro Raio-X','Registre os valores de um mês para ver os resultados.','Começar','finance'))}`;const f=o.result;
 const main=[['Faturamento',money(f.revenue,false),'trending-up'],['Saídas operacionais',money(f.revenue-f.operating,false),'wallet'],['Resultado operacional',money(f.operating,false),'chart-bar'],['Ponto de equilíbrio',f.breakEven===null?'Não aplicável':money(f.breakEven,false),'equal']];
 const more=[['Custos variáveis',money(f.cv)],['Margem de contribuição',money(f.mc)],['Margem (%)',num(f.mcPct*100)+'%'],['Custos fixos',money(f.fixed)],['Sobra mensal',money(f.liquid)],['Sobra após dívidas',money(f.afterDebt)],['Ticket médio',f.ticket===null?'Não aplicável':money(f.ticket)],['Folga sobre equilíbrio',f.slack===null?'Não aplicável':num(f.slack*100)+'%'],['Meses de reserva',f.months===null?'Não aplicável':num(f.months)+' meses'],['Peso das parcelas',f.debtWeight===null?'Não aplicável':num(f.debtWeight*100)+'%'],['Retirada cobre a casa?',money(f.houseLeft)]];
 const lights=[['Casa e empresa separadas','separate'],['Sobra após dívidas','after'],['Folga no equilíbrio','slack'],['Meses de reserva','reserve'],['Peso das parcelas','debt'],['Retirada cobre a casa','house']];
 return `${head('Seu Raio-X financeiro','Um retrato do seu negócio para decidir com mais segurança.',button('Imprimir relatório','print'))}<div class="financial-kpis">${main.map(([title,val,ic],i)=>`<section class="panel financial-kpi">${sq(ic,i%2?'orange':'')}<div><small>${title}</small><strong>${val}</strong><span>${i===2?num(f.mcPct*100)+'% de margem de contribuição':i===3&&f.slack!==null?'Folga de '+num(f.slack*100)+'%':'Referência: '+esc(o.month)}</span></div></section>`).join('')}</div><div class="layout-grid"><div class="c8">${panel('Evolução mensal',C.plot(financeRows(),{bars:true}),go('Ver histórico','history','link'))}</div><div class="c4">${panel('O que seus números mostram',`<div class="reading-highlight">${sq('wallet','orange')}<h3>${f.afterDebt<0?'É hora de ajustar a rota.':'Sua próxima decisão começa aqui.'}</h3></div><p class="reading-text">Seu resultado operacional é <b>${money(f.operating)}</b>. Depois da retirada do dono e das parcelas da empresa, a sobra é <b>${money(f.afterDebt)}</b>.</p><div class="divider"></div><p class="reading-text">${f.breakEven===null?'Revise preços e custos: sua margem não permite calcular o ponto de equilíbrio.':'Você precisa faturar '+money(f.breakEven)+' por mês para cobrir os custos e a retirada.'}</p>${go('Organizar com o Kit','kit','primary full')}`)}</div><div class="c6">${panel('Seu semáforo financeiro',`<div class="traffic-grid">${lights.map(([n,k])=>`<div class="traffic-row"><i class="dot ${f.traffic[k]}"></i>${n}<b>${({verde:'Saudável',amarelo:'Atenção',vermelho:'Revisar',indisponivel:'Sem dados'})[f.traffic[k]]}</b></div>`).join('')}</div>`)}</div><div class="c6">${panel('Suas próximas ações',`<ol class="action-list">${f.steps.map((text,i)=>`<li><span>0${i+1}</span><p>${esc(text)}</p></li>`).join('')}</ol>`)}</div><div class="c12"><details class="panel result-details"><summary>Ver todos os indicadores ${icon('chevron-down',18)}</summary><div class="result-metrics">${more.map(([k,v])=>kpi(k,v)).join('')}</div>${f.mcPct<=0?'<div class="alert-inline">Cada venda custa mais do que rende. Revise preço e custos antes de vender mais.</div>':''}</details></div></div><div class="result-bottom"><p>Esta ferramenta organiza informações para a sua decisão. Não é recomendação financeira e não substitui o seu contador.</p>${go('Fazer novo Raio-X','finance','link')}</div>`;
}

function historyPage(){const tab=state.historyTab;const entries=tab==='diag'?state.diagnostics:state.finances;
 const diagCompare=state.diagnostics.length>1?(()=>{let a=state.diagnostics[0].result,b=state.diagnostics.at(-1).result;return `<div class="divider"></div><h3 class="panel-title" style="margin:13px 0">Comparação: inicial × mais recente</h3><div class="result-metrics">${RA.map(k=>kpi(k,`${num(a.radar[k].score,0)} → ${num(b.radar[k].score,0)}`,`Diferença ${num(b.radar[k].score-a.radar[k].score)>0?'+':''}${num(b.radar[k].score-a.radar[k].score)} ponto(s)`)).join('')}</div><p class="subtle-footnote">A comparação usa as notas registradas no seu primeiro diagnóstico e no mais recente.</p>`;})():'';
 return `${head('Histórico e evolução','Acompanhe diagnósticos e análises anteriores sem perder os dados originais.')}${tab==='finance'&&state.finances.length?panel('Evolução dos seus números',C.plot(financeRows(),{bars:true})):''}<section class="panel history-panel"><div class="panel-head"><h2 class="panel-title">Seus registros</h2><div class="pill-tabs"><button class="tab ${tab==='diag'?'active':''}" data-action="history-diag">Diagnósticos</button><button class="tab ${tab==='finance'?'active':''}" data-action="history-finance">Raio-X financeiro</button></div></div>${entries.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Data</th><th>Tipo</th><th>Resultado</th><th></th></tr></thead><tbody>${entries.map((e,i)=>`<tr><td>${dateBR(e.created)}</td><td>${tab==='diag'?(i===0?'Inicial':'Refeito'):'Raio-X '+esc(e.month)}</td><td>${tab==='diag'?'Radar '+num(e.result.mediaRadar):money(e.result.afterDebt)}</td><td><button class="btn small" data-action="${tab==='diag'?'view-diagnostic':'view-finance'}" data-id="${e.id}">Ver resultado ${icon('arrow-right',14)}</button></td></tr>`).join('')}</tbody></table></div>${tab==='diag'?diagCompare:''}`:empty('Seu histórico está vazio','Seus resultados anteriores aparecerão aqui conforme você concluir análises.',tab==='diag'?'Fazer diagnóstico':'Fazer Raio-X',tab==='diag'?'diagnostic':'finance')}</section>`;
}
function kitEssentialPage(){return `${head('Kit Essencial','Ferramentas práticas para organizar os números e abrir novas conversas.',has('essencial')?badge('Seu acesso está liberado','good'):badge('Conheça as ferramentas','blue'))}<div class="essential-grid">${KIT.slice(0,2).map(([route,title,desc,ic],i)=>`<section class="panel essential-card">${sq(ic,i?'orange':'')}<div><h2>${title}</h2><p>${desc}</p>${go(has('essencial')?'Acessar ferramenta':'Conhecer o Kit',has('essencial')?route:'kit','primary')}</div></section>`).join('')}</div><div class="callout-card essential-upgrade">${sq('crown','orange')}<div><h3>Mais estrutura para colocar em prática.</h3><p>Conheça as cinco ferramentas e o Plano de 90 Dias do Kit UP Completo.</p></div>${go('Explorar Kit Completo','kit','orange')}</div>`;}
function kitPage(){return `${head('Kit UP Completo','Ferramentas práticas para aplicar o que você descobriu no Diagnóstico e no Raio-X.',has('kit')?badge('Kit Completo ativo','good'):has('essencial')?badge('Kit Essencial ativo','blue'):badge('Acesso bloqueado'))}<div class="layout-grid"><div class="c12">${panel('Ferramentas do Kit',`<div class="kit-grid">${KIT.map(([route,title,desc,ic],i)=>{let unlocked=i<2?has('essencial'):has('kit');return `<div class="kit-tile"><div class="row-between">${sq(ic,i===2?'orange':'')} ${badge(unlocked?'Liberado':'Bloqueado',unlocked?'good':'')}</div><h3>${title}</h3><p>${desc}</p>${unlocked?go('Abrir ferramenta',route,'primary'):`<div class="notice-box">${icon('lock',15)} ${i<2?'Disponível no Kit UP Essencial ou Completo.':'Disponível no Kit UP de Implementação.'}</div>`}</div>`}).join('')}</div>` )}</div>${!has('kit')?`<div class="c12"><div class="callout-card"><div><h3>Conheça o Kit UP Completo</h3><p>As cinco ferramentas são liberadas conforme a compra na Kiwify.</p></div>${state.admin.kitLink?`<a class="btn orange" href="${esc(state.admin.kitLink)}" target="_blank" rel="noopener noreferrer">Ver página de compra ${icon('arrow-up-right')}</a>`:'<span class="badge orange">Link de compra pendente no admin</span>'}</div></div>`:''}</div>`;}
function lockedPage(title){return `${head(title,'Acesso conforme o produto adquirido na Kiwify.')}${panel('Funcionalidade bloqueada',empty('Esta ferramenta não está disponível na sua conta','Na versão final, a permissão será concedida automaticamente pelo webhook da Kiwify.', 'Conhecer o Kit', 'kit'))}`;}
function ledgerPage(){if(!has('essencial'))return lockedPage('Raio-X automático');
 const month=state.financeViewMonth||today().slice(0,7),list=state.kitTransactions.filter(t=>t.date.slice(0,7)===month),income=list.filter(t=>t.type==='entrada').reduce((sum,t)=>sum+Number(t.value),0),expense=list.filter(t=>t.type==='saida').reduce((sum,t)=>sum+Number(t.value),0);
 const tx=state.kitTransactions.find(t=>String(t.id)===String(state.editingTransaction))||{},bill=state.kitBills.find(t=>String(t.id)===String(state.editingBill))||{};
 const unpaid=state.kitBills.filter(b=>!b.paid),due=unpaid.filter(b=>new Date(b.due+'T12:00:00')<=new Date(Date.now()+7*86400000));
 return `${head('Raio-X automático','Registre, edite e acompanhe os movimentos do seu negócio.',button('Exportar CSV','export-csv'))}<div class="layout-grid"><div class="c12">${panel('Resumo do mês',`<div class="toolbar">${field('Mês de referência','kit_month',month,'month')}</div><div class="result-metrics">${kpi('Entradas registradas',money(income))}${kpi('Saídas registradas',money(expense))}${kpi('Saldo registrado',money(income-expense))}${kpi('Contas em aberto',money(unpaid.reduce((sum,b)=>sum+Number(b.value),0)))}</div>`)}</div><div class="c8">${panel('Lançamentos',`${list.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Movimento</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.desc)}</td><td>${esc(t.category)}</td><td>${badge(t.type==='entrada'?'Entrada':'Saída',t.type==='entrada'?'blue':'orange')}</td><td>${money(t.value)}</td><td><div class="btn-row"><button class="btn small" data-action="edit-transaction" data-id="${esc(t.id)}" aria-label="Editar ${esc(t.desc)}">${icon('pen-line',14)}</button><button class="btn small danger" data-action="del-transaction" data-id="${esc(t.id)}" aria-label="Excluir ${esc(t.desc)}">${icon('x',14)}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum lançamento neste mês','Adicione uma entrada ou saída para começar.')}<div class="divider"></div><h3 class="panel-title">${tx.id?'Editar lançamento':'Novo lançamento'}</h3><form id="transaction-form" class="interactive-form"><div class="form-grid">${field('Data','date',tx.date||today(),'date','','required')}${field('Descrição','desc',tx.desc||'','text','','required')}${field('Valor (R$)','value',tx.value||'','number','','required min="0.01" step="0.01"')}${select('Movimento','type',[['entrada','Entrada'],['saida','Saída']],tx.type||'entrada')}${select('Categoria','category',CAT,tx.category||'vendas')}${select('Pertence a','scope',[['empresa','Empresa'],['pessoal','Casa/pessoal']],tx.scope||'empresa')}</div><div class="btn-row form-actions"><button class="btn primary" type="submit">${tx.id?'Salvar alteração':'Adicionar lançamento'}</button>${tx.id?button('Cancelar edição','cancel-transaction','ghost'):''}</div></form>`)}</div><div class="c4">${panel('Contas a pagar',`${due.length?`<div class="alert-inline">${due.length} conta(s) vencida(s) ou com vencimento próximo.</div>`:''}<div class="link-list bills-list">${state.kitBills.slice().reverse().map(b=>`<div class="button-card"><div class="list-content"><b>${esc(b.desc)}</b><p>${dateBR(b.due)} · ${money(b.value)}</p><div class="btn-row"><button class="btn small" data-action="toggle-bill" data-id="${esc(b.id)}">${b.paid?'Pago · reabrir':'Marcar pago'}</button><button class="btn small" data-action="edit-bill" data-id="${esc(b.id)}" aria-label="Editar conta ${esc(b.desc)}">${icon('pen-line',14)}</button><button class="btn small danger" data-action="delete-bill" data-id="${esc(b.id)}" aria-label="Excluir conta ${esc(b.desc)}">${icon('x',14)}</button></div></div></div>`).join('')}</div><h3 class="panel-title form-section-title">${bill.id?'Editar conta':'Nova conta'}</h3><form id="bill-form" class="interactive-form"><div class="form-grid">${field('Conta','desc',bill.desc||'','text','','required')}${field('Valor (R$)','value',bill.value||'','number','','required min="0.01" step="0.01"')}${field('Vencimento','due',bill.due||today(),'date','','required')}</div><div class="btn-row form-actions"><button class="btn primary" type="submit">${bill.id?'Salvar conta':'Adicionar conta'}</button>${bill.id?button('Cancelar','cancel-bill','ghost'):''}</div></form>`)}</div><div class="c12">${panel('Simulador de quitação',`<p class="panel-sub">Veja como a parcela e um pagamento extra mudam o prazo de quitação.</p><form id="sim-debt" class="form-grid four interactive-form">${field('Saldo devedor (R$)','balance','','number','','required min="0.01"')}${field('Juros ao mês (%)','rate','0','number','','required')}${field('Parcela mensal (R$)','payment','','number','','required min="0.01"')}${field('Pagamento extra (R$)','extra','0','number')}<div class="wide"><button class="btn primary" type="submit">Simular quitação</button></div></form><div id="sim-output" aria-live="polite"></div>`)}</div></div>`;
}

function scriptsPage(){if(!has('essencial'))return lockedPage('Roteiros de prospecção');let current=state.messageTemplates.find(s=>String(s.id)===String(state.selectedScript))||state.messageTemplates[0];return `${head('Roteiros de prospecção e indicação','Escolha uma situação, personalize as variáveis e copie a mensagem para enviar ao contato.') }<div class="layout-grid"><div class="c5">${panel('Biblioteca de roteiros',`<div class="link-list">${state.messageTemplates.map(s=>`<button class="button-card" style="width:100%;border-color:${s.id==current.id?'#0031E8':'#E3E8F0'}" data-action="choose-script" data-id="${esc(s.id)}">${sq('message-circle')}<span class="list-content"><b>${esc(s.title)}</b><p>${s.id<=5?'Modelo ilustrativo — validar com a Bring':'Modelo cadastrado na prévia'}</p></span>${icon('chevron-right',16)}</button>`).join('')}</div>` )}</div><div class="c7">${panel('Personalizar mensagem',`<p class="muted-label" style="margin-bottom:17px">${esc(current.title)}</p><div class="form-grid">${field('Nome do contato','script_name',state.scriptVars?.name||'','text','Ex.: Maria')}${field('Seu serviço ou produto','script_service',state.scriptVars?.service||'','text','Ex.: consultoria')}</div><div id="script-preview" class="quote" style="margin:18px 0">${esc(current.text.replaceAll('{nome}',state.scriptVars?.name||'[nome]').replaceAll('{serviço}',state.scriptVars?.service||'[serviço]'))}</div><div class="btn-row">${button('Copiar mensagem','copy-script','primary')}${button('Abrir no WhatsApp','whatsapp-script')}</div><p class="subtle-footnote">Mensagens de exemplo editáveis pelo administrador. O conteúdo definitivo será fornecido pela Bring.</p>` )}</div></div>`;}
function offersPage(){if(!has('kit'))return lockedPage('Ofertas modelo');const o=state.offerDraft||state.personalOffers.find(x=>String(x.id)===String(state.editingOffer))||state.personalOffers.at(-1)||{};
 return `${head('Ofertas modelo','Escolha uma base, personalize sua oferta e guarde as versões que quiser.')}<div class="layout-grid"><div class="c12">${panel('Escolha um ponto de partida',`<div class="offer-template-grid">${OFFERS.map((name,i)=>`<button class="offer-template" data-action="template-offer" data-template="${i}">${sq('file-text',i%2?'orange':'')}<span>${name}</span>${icon('arrow-up-right',16)}</button>`).join('')}</div>`)}</div><div class="c8">${panel('Minha Oferta em Uma Página',`<form id="offer-form" class="interactive-form"><div class="form-grid">${field('Nome da oferta','name',o.name||'','text','','required')}${select('Tipo de negócio','type',OFFERS,o.type||OFFERS[0])}${field('Público','audience',o.audience||'','text','','required')}${field('Problema principal','problem',o.problem||'','text','','required')}${ta('Promessa / resultado esperado','promise',o.promise||'')}${ta('Solução / entrega','delivery',o.delivery||'')}${ta('Provas e diferenciais','proof',o.proof||'')}${ta('Condições','terms',o.terms||'')}${ta('Próximo passo (CTA)','cta',o.cta||'')}</div><div class="btn-row form-actions"><button class="btn primary" type="submit">Salvar oferta</button>${button('Criar nova','new-offer','ghost')}</div></form>`)}</div><div class="c4">${panel('Ofertas salvas',state.personalOffers.length?`<div class="link-list">${state.personalOffers.map(x=>`<div class="button-card"><div class="list-content"><b>${esc(x.name)}</b><p>${esc(x.type)} · ${dateBR(x.saved)}</p><div class="btn-row"><button class="btn small" data-action="edit-offer" data-id="${esc(x.id)}">Editar</button><button class="btn small danger" data-action="delete-offer" data-id="${esc(x.id)}">Excluir</button></div></div></div>`).join('')}</div>`:empty('Sua primeira oferta começa aqui','Preencha o editor e salve para consultar depois.'))}</div></div>`;
}

function planPage(){if(!has('kit'))return lockedPage('Plano de 90 Dias');const p=state.plan,area=state.diagnostics.at(-1)?.result.gargalo||'',model=L.planTemplate(area);let weeks=state.checkins.slice().reverse();return `${head('Plano de 90 Dias','Organize prioridades e registre a revisão semanal. O plano é sempre editável.')}<div class="layout-grid"><div class="c8">${panel('Plano de implementação',`<details class="plan-template"><summary>Modelo inicial${area?' · '+esc(area):''}${icon('chevron-down',16)}</summary><div class="plan-template-body"><p>Uma base editável para revisar e adaptar ao seu negócio.</p><h3>${esc(model.result)}</h3><ol>${['phase1','phase2','phase3'].map((key,i)=>`<li><b>Dias ${i*30+1} a ${(i+1)*30}:</b> ${esc(model[key])}</li>`).join('')}</ol>${button('Preencher campos vazios','apply-plan-template')}<small>O que você já escreveu será preservado. Revise o modelo antes de salvar.</small></div></details><form id="plan-form"><div class="form-grid">${ta('Resultado desejado ao final de 90 dias','result',p.result)}${['decision1','decision2','decision3','decision4'].map((k,i)=>ta(`Decisão principal ${i+1}`,k,p[k])).join('')}${ta('Fase 1 · primeiros 30 dias','phase1',p.phase1)}${ta('Fase 2 · dias 31 a 60','phase2',p.phase2)}${ta('Fase 3 · dias 61 a 90','phase3',p.phase3)}${select('Dia preferido para check-in','reminder',['segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado','domingo'],p.reminder)}</div><button type="submit" class="btn primary" style="margin-top:16px">${icon('check')} Salvar meu plano</button><p class="subtle-footnote">O envio de lembrete por e-mail dependerá de serviço transacional integrado.</p></form>` )}</div><div class="c4">${panel('Check-in semanal',`<p class="muted-label" style="margin-bottom:13px">Perguntas provisórias para validar com a Bring — a lista exata da aula F.1 não veio no documento.</p><form id="checkin-form" class="form-grid">${['O que avancei na semana?','Qual resultado observei?','O que ficou travado?','Que ajuste preciso fazer?','Qual é minha próxima prioridade?'].map((q,i)=>ta(q,`q${i+1}`)).join('')}<button type="submit" class="btn primary">Salvar check-in</button></form>` )}</div><div class="c12">${panel('Histórico de check-ins',weeks.length?`<div class="link-list">${weeks.map(w=>`<div class="button-card"><span class="square-icon">${icon('calendar')}</span><span class="list-content"><b>${dateBR(w.date)}</b><details class="checkin-details"><summary>Ver revisão semanal</summary>${w.answers.map((answer,i)=>`<p><b>${['Avanços','Resultados','Dificuldades','Ajustes','Próxima prioridade'][i]}:</b> ${esc(answer||'Não informado')}</p>`).join('')}</details></span></div>`).join('')}</div>`:empty('Ainda não há check-ins','Registre uma revisão semanal para acompanhar sua execução.'))}</div></div>`;}
function proceduresPage(){if(!has('kit'))return lockedPage('Kit de transferência');const o=state.procedures.find(x=>String(x.id)===String(state.editingProcedure))||{};return `${head('Kit de transferência','Documente a tarefa, combine o padrão e acompanhe a execução.',button('Imprimir procedimentos','print'))}<div class="layout-grid"><div class="c7">${panel(o.id?'Editar procedimento':'Novo procedimento',`<form id="procedure-form" class="interactive-form"><div class="form-grid">${field('Nome da tarefa','task',o.task||'','text','','required')}${field('Responsável','owner',o.owner||'','text','','required')}${ta('Objetivo','goal',o.goal||'')}${field('Prazo','deadline',o.deadline||'','text','Ex.: toda sexta-feira, às 16h')}${ta('Passos de execução','steps',o.steps||'','Uma etapa por linha')}${ta('Padrão de qualidade','standard',o.standard||'')}${ta('O que fazer se der errado','fallback',o.fallback||'')}</div><div class="btn-row form-actions"><button class="btn primary" type="submit">Salvar procedimento</button>${o.id?button('Cancelar edição','cancel-procedure','ghost'):''}</div></form>`)}</div><div class="c5">${panel('Procedimentos salvos',state.procedures.length?`<div class="link-list">${state.procedures.map(x=>`<details class="procedure-record"><summary><span><b>${esc(x.task)}</b><small>${esc(x.owner)} · ${dateBR(x.created)}</small></span>${icon('chevron-down',16)}</summary><div class="procedure-body"><p><b>Objetivo:</b> ${esc(x.goal||'Não informado')}</p><p><b>Prazo:</b> ${esc(x.deadline||'Não informado')}</p><ol>${String(x.steps||'').split('\n').filter(Boolean).map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p><b>Padrão:</b> ${esc(x.standard||'Não informado')}</p><p><b>Se algo der errado:</b> ${esc(x.fallback||'Não informado')}</p><div class="btn-row"><button class="btn small" data-action="edit-procedure" data-id="${esc(x.id)}">Editar</button><button class="btn small danger" data-action="delete-procedure" data-id="${esc(x.id)}">Excluir</button></div></div></details>`).join('')}</div>`:empty('Nenhum procedimento ainda','Seu primeiro processo documentado aparecerá aqui.'))}</div></div>`;}

function profilePage(){if(backend||visualPreview)return integratedProfile();return `${head('Minha conta','Gerencie os dados da prévia e teste os diferentes estados de permissão.')}<div class="layout-grid"><div class="c6">${panel('Dados da conta',`<form id="profile-form" class="form-grid">${field('Nome','name',state.user.name,'text','','required')}${field('E-mail','email',state.user.email,'email','','required')}<div class="wide"><button class="btn primary" type="submit">Salvar alterações locais</button></div></form><p class="subtle-footnote">Na versão de produção, a alteração de e-mail será gerida pelo suporte e auditada no servidor.</p>` )}</div><div class="c6">${panel('Prévia dos acessos por compra',`<div class="notice-box" style="margin-bottom:14px">${icon('info')}<span>Simulador exclusivo do frontend para verificar estados de interface. Não concede permissões reais nem consulta a Kiwify.</span></div><div class="link-list">${[['front','Produto principal · Diagnóstico e Raio-X'],['essencial','Kit Essencial · 2 ferramentas'],['kit','Kit UP Completo · 5 ferramentas']].map(([k,t])=>`<label class="form-checkbox" style="padding:9px 0"><input data-entitlement="${k}" type="checkbox" ${state.entitlements[k]?'checked':''}>${t}</label>`).join('')}</div>` )}</div><div class="c6">${panel('Privacidade e dados',`<div class="link-list">${button('Exportar meus dados de demonstração (JSON)','export-json','full')}${button('Apagar os dados desta demonstração','clear-data','danger full')}</div><p class="subtle-footnote">Exclusão e exportação reais de conta precisarão de endpoints autenticados, conforme a LGPD.</p>` )}</div><div class="c6">${panel('Termos e transparência',`<div class="readout"><h3>Uso dos seus dados</h3><p>${esc(TERMS)}</p><p>Os indicadores e as orientações são calculados por regras do sistema a partir das informações preenchidas.</p></div><p style="margin-top:12px">${state.consent?badge('Aceite de demonstração registrado','good'):badge('Aceite não registrado')}</p>` )}</div></div>`;}
function supportPage(){return `${head('Ajuda e suporte','Dúvidas de acesso, resultados ou dados? Veja os canais e orientações.')}<div class="layout-grid"><div class="c8">${panel('Perguntas frequentes',`<div class="link-list">${[['Como acesso o software?','Na produção, use o mesmo e-mail da compra para receber um código de seis dígitos válido por dez minutos.'],['Onde encontro as aulas?','As aulas permanecem na área de membros da Kiwify. O Software UP é um aplicativo separado.'],['Por que o Kit está bloqueado?','O acesso depende da compra aprovada do Kit Essencial ou Kit de Implementação, cada um com permissões próprias.'],['A análise financeira substitui meu contador?','Não. O Raio-X organiza informações para tomada de decisão, sem substituir orientação contábil.']].map(([q,a])=>`<details class="button-card" style="display:block"><summary style="font-size:13px;font-weight:650;cursor:pointer">${q}</summary><p style="font-size:12px;line-height:1.6;color:#536174;margin-top:12px">${a}</p></details>`).join('')}</div>`)}</div><div class="c4">${panel('Suporte da UP',`<p style="color:#5D697C;font-size:13px;line-height:1.6">O canal oficial de suporte deverá ser configurado antes do lançamento.</p><p class="subtle-footnote">Não publique números ou e-mails fictícios no frontend.</p>`)}</div></div>`;}
function adminPage(){let tab=state.adminTab;const tabs=[['overview','Visão geral'],['students','Alunos e acessos'],['webhooks','Eventos Kiwify'],['products','Produtos'],['content','Conteúdo'],['reports','Relatórios'],['config','Configurações']];if(!tabs.some(([key])=>key===tab))tab='overview';let main='';
 if(tab==='overview')main=`<div class="notice-box">${icon('info')}<span>Prévia administrativa com os dados ilustrativos desta interface.</span></div><div class="admin-overview-kpis result-metrics">${kpi('Alunos nesta prévia','1')}${kpi('Diagnósticos realizados',state.diagnostics.length)}${kpi('Análises financeiras',state.finances.length)}${kpi('Ferramentas disponíveis',has('kit')?'5':has('essencial')?'2':'0')}</div><div class="layout-grid"><div class="c7">${panel('Gargalos identificados',C.donut(RA.map(name=>({name,value:state.diagnostics.filter(d=>d.result.gargalo===name).length})),'Gargalos do Radar'))}</div><div class="c5">${panel('Atividade recente',`<div class="link-list">${state.diagnostics.slice(-3).map(d=>`<div class="button-card">${sq('clipboard-check')}<span class="list-content"><b>Diagnóstico concluído</b><p>${dateBR(d.created)} · Radar ${num(d.result.mediaRadar)}</p></span>${badge('Concluído','blue')}</div>`).join('')||empty('Sem atividade ainda','Os diagnósticos concluídos aparecerão aqui.')}</div>`)}</div></div>`;
 if(tab==='students')main=`<div class="notice-box" style="margin-bottom:16px">${icon('info')}<span>Exemplo de conta local. Liberação ou revogação de acesso aqui não altera vendas reais nem a Kiwify.</span></div><div class="table-scroll"><table class="table"><thead><tr><th>Aluno</th><th>E-mail</th><th>Produto principal</th><th>Essencial</th><th>Kit Completo</th></tr></thead><tbody><tr><td>${esc(state.user.name)}</td><td>${esc(state.user.email||'Prévia sem e-mail')}</td>${['front','essencial','kit'].map(k=>`<td>${badge(state.entitlements[k]?'Liberado':'Não liberado',state.entitlements[k]?'good':'')}</td>`).join('')}</tr></tbody></table></div>${go('Editar acesso de demonstração','profile','small')}`;
 if(tab==='webhooks')main=`${empty('Sem webhooks conectados','O backend deverá receber assinatura válida, deduplicar eventos, armazenar payload e processar aprovação, reembolso e chargeback.')}<div class="notice-box">${icon('lock')} <span>O endpoint POST /webhooks/kiwify, a verificação HMAC-SHA1 e o reprocessamento são responsabilidades do backend.</span></div>`;
 if(tab==='products')main=`<form id="admin-products" class="form-grid">${field('ID Kiwify do produto principal','front',state.admin.productIds.front)}${field('ID Kiwify do Kit Essencial','essencial',state.admin.productIds.essencial)}${field('ID Kiwify do Kit Completo','kit',state.admin.productIds.kit)}<div class="wide"><button class="btn primary" type="submit">Salvar mapa local</button></div></form><p class="subtle-footnote">Os IDs reais devem ser validados via payload do webhook da Kiwify antes da integração.</p>`;
 if(tab==='content')main=`<div class="notice-box">${icon('info')}<span>Os roteiros abaixo são modelos ilustrativos. A Bring deverá enviar textos oficiais, as ofertas e os versículos aprovados.</span></div><div class="table-scroll" style="margin-top:15px"><table class="table"><thead><tr><th>Modelo de roteiro</th><th>Status</th></tr></thead><tbody>${state.messageTemplates.map(s=>`<tr><td>${esc(s.title)}</td><td>${badge('Exemplo','orange')}</td></tr>`).join('')}</tbody></table></div><form id="admin-script" style="margin-top:18px"><div class="form-grid">${field('Nome do roteiro','title','','text','','required')}${ta('Mensagem com variáveis {nome} e {serviço}','text')}</div><button class="btn primary" style="margin-top:12px" type="submit">Adicionar modelo local</button></form>`;
 if(tab==='reports')main=`<div class="notice-box" style="margin-bottom:15px">${icon('info')}<span>Somente dados locais da demonstração; os relatórios de produção deverão ser agregados e anônimos, sem expor os números dos alunos para o suporte.</span></div><div class="result-metrics">${kpi('Usuários de demonstração','1')}${kpi('Diagnósticos feitos',state.diagnostics.length)}${kpi('Raio-X salvos',state.finances.length)}${kpi('Kit liberado',has('essencial')?'Sim':'Não')}</div>${state.diagnostics.length?`<div class="divider"></div><h3 class="panel-title">Gargalos identificados (demonstração)</h3><p class="panel-sub">${esc(state.diagnostics.map(d=>d.result.gargalo).join(' · '))}</p>`:''}`;
 if(tab==='config')main=`<form id="admin-config" class="form-grid">${field('URL oficial da compra do Kit','kitLink',state.admin.kitLink,'url','Somente URLs HTTPS válidas')}<div class="wide"><button class="btn primary" type="submit">Salvar configurações</button></div></form><div class="divider"></div><p class="panel-sub">Para ativação em produção: integração com a Kiwify, e-mail, configuração do banco, aprovação dos conteúdos e política de backups.</p>`;
 return `${head('Painel administrativo · prévia','Acompanhe os acessos, as ferramentas e a atividade da plataforma.',badge('Prévia visual','blue'))}<div class="layout-grid"><div class="c12">${panel('Gestão da Plataforma UP',`<div class="pill-tabs" style="width:100%;margin-bottom:22px">${tabs.map(([k,t])=>`<button class="tab ${tab===k?'active':''}" data-admin-tab="${k}">${t}</button>`).join('')}</div>${main}`)}</div></div>`;}
const routes={dashboard,diagnostic:diagnosticPage,'diagnostic-result':diagnosticResult,finance:financePage,'finance-result':financeResult,history:historyPage,kit:kitPage,'kit-essential':kitEssentialPage,ledger:ledgerPage,scripts:scriptsPage,offers:offersPage,plan:planPage,procedures:proceduresPage,profile:profilePage,support:supportPage,admin:adminPage};
function render(){if(loading){$('#app').innerHTML='<div class="auth-right"><p>Carregando sua conta…</p></div>';return;}if(backend&&active==='admin')active='dashboard';if(!state.signed&&!['login','code'].includes(active))active='login';if(state.signed&&['login','code'].includes(active))active='dashboard';if(active==='diagnostic-result'&&!state.diagnostics.length)active='diagnostic';if(active==='finance-result'&&!state.finances.length)active='finance';document.title=(navItems().find(i=>i[0]===active)?.[1]||'Software UP')+' · Universo do Propósito';$('#app').innerHTML=['login','code'].includes(active)?authPage():appShell((['diagnostic','diagnostic-result','finance','finance-result','history'].includes(active)&&!has('front')?lockedPage('Acesso ao produto principal'): (routes[active]||dashboard)()));if(backend){const strip=$('.demo-strip');if(strip)strip.innerHTML='<span id="sync-status">Conectado ao servidor.</span>';const meta=$('.user-meta small');if(meta)meta.textContent='Conta do aluno';}if(window.UP)UP.hydrate();if(C)C.hydrate();if(window.UPMenu)window.UPMenu.hydrate();if(window.UPForms)window.UPForms.hydrate();}
// Para a prévia, preservar dados durante navegação usando DOM e estado local. Produção usará APIs autenticadas.
function captureDraft(){let page=active;
 if(page==='finance'){const f=state.financeDraft;for(let n of ['revenue','sales','owner','house','reserveCompany','reservePersonal','separate','month']){let el=document.querySelector(`[name="${n}"]`);if(el)f[n]=el.value;}
  for(let [k] of FIN_FIX){let el=document.querySelector(`[name="fixed_${k}"]`);if(el)f.fixed[k]=el.value;}
  let est=document.querySelector('[name="estimated"]');if(est)f.estimated=est.checked;
  document.querySelectorAll('[data-fv]').forEach(el=>{let k=el.dataset.fv;f.variable[k]=f.variable[k]||{};f.variable[k].value=el.value;});document.querySelectorAll('[data-fu]').forEach(el=>{let k=el.dataset.fu;f.variable[k]=f.variable[k]||{};f.variable[k].unit=el.value;});
 }
 if(page==='diagnostic'){document.querySelectorAll('[data-evidence-name]').forEach(el=>{let g=el.dataset.evidenceGroup,n=el.dataset.evidenceName;state.diagnosticDraft[g][n]=state.diagnosticDraft[g][n]||{};state.diagnosticDraft[g][n].evidence=el.value;});}
 save();}
const validateScores=g=>{let names=g==='roda'?RO:RA;return names.every(n=>state.diagnosticDraft[g][n]?.score!==undefined)};
async function navStep(delta){captureDraft();if(active==='diagnostic'){if(delta>0){if(state.diagStep===0&&!validateScores('roda'))return flash('Atribua uma nota a todas as 8 dimensões.');if(state.diagStep===1&&!validateScores('radar'))return flash('Atribua uma nota às 4 áreas do Radar.');}state.diagStep=Math.max(0,Math.min(2,state.diagStep+delta));save();render();window.scrollTo(0,0)}
 if(active==='finance'){if(delta>0&&state.finStep===0&&!(Number(state.financeDraft.revenue)>0))return flash('Informe o faturamento mensal maior que zero.');if(delta>0&&state.finStep===0&&!(Number(state.financeDraft.sales)>0))return flash('Informe a quantidade de vendas maior que zero.');if(delta>0&&state.finStep===5){const f=state.financeDraft,res=L.finance(f),month=f.month||today().slice(0,7);let entry={id:Date.now(),created:today(),month,input:JSON.parse(JSON.stringify(f)),result:res};state.selectedFinance=entry.id;let idx=state.finances.findIndex(x=>x.month===month);if(idx>=0)state.finances[idx]=entry;else state.finances.push(entry);save();if(backend?.flush)await backend.flush();state.finStep=0;if(!backend)save();flash('Raio-X calculado e salvo.');navigate('finance-result');return;}state.finStep=Math.max(0,Math.min(5,state.finStep+delta));save();render();window.scrollTo(0,0);}
}
function downloadFile(filename,data,mime){const b=new Blob([data],{type:mime}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(s){try{await navigator.clipboard.writeText(s);flash('Texto copiado.');}catch(e){flash('Permissão de cópia não disponível neste navegador.');}}
function scriptText(){let s=state.messageTemplates.find(x=>String(x.id)===String(state.selectedScript))||state.messageTemplates[0];return s.text.replaceAll('{nome}',$('[name="script_name"]')?.value||'[nome]').replaceAll('{serviço}',$('[name="script_service"]')?.value||'[serviço]');}
function changeTarget(e){const el=e.target;
 if(el.matches('[data-entitlement]')&&!backend){state.entitlements[el.dataset.entitlement]=el.checked;save();flash('Permissão alterada somente na demonstração.');render();}
 if(el.matches('[data-evidence-name]')){let g=el.dataset.evidenceGroup,n=el.dataset.evidenceName;state.diagnosticDraft[g][n]=state.diagnosticDraft[g][n]||{};state.diagnosticDraft[g][n].evidence=el.value;save();}
 if(el.name==='kit_month'){state.financeViewMonth=el.value;save();render();}
 if(el.name==='script_name'||el.name==='script_service'){state.scriptVars={name:$('[name="script_name"]')?.value||'',service:$('[name="script_service"]')?.value||''};$('#script-preview').textContent=scriptText();save();}
 if(el.closest?.('#sim-debt'))updateDebtPreview();
 if(active==='finance'&&(el.matches('[data-fv],[data-fu]')||el.name?.startsWith('fixed_')||['revenue','sales','owner','house','separate','reserveCompany','reservePersonal','month','estimated'].includes(el.name))){captureDraft();updateFinancePreview();}
}
async function doAction(el){const action=el.dataset.action;
 if(action==='apply-plan-template'){
  const form=document.querySelector('#plan-form'),current=formData(form),area=state.diagnostics.at(-1)?.result.gargalo||'',next=L.applyPlanTemplate(current,area);let count=0;
  for(const [key,value]of Object.entries(next)){const field=form.elements.namedItem(key);if(field&&field.value!==value){field.value=value;count++;}}
  if(count)window.UPForms?.capture(form);
  window.UPForms?.feedback(form,count?'Campos vazios preenchidos com o modelo. Revise e salve o plano.':'Seu plano já está preenchido. Nenhum campo foi alterado.',count?'pending':'success');
  return;
 }

 const edits={'edit-transaction':['editingTransaction','transaction-form'],'edit-bill':['editingBill','bill-form'],'edit-offer':['editingOffer','offer-form'],'edit-procedure':['editingProcedure','procedure-form']};
 if(edits[action]){const [key,formId]=edits[action];state[key]=el.dataset.id;if(action==='edit-offer')state.offerDraft=null;window.UPForms?.clear(formId);render();document.querySelector('#'+formId+' input')?.focus();return;}
 const cancel={'cancel-transaction':['editingTransaction','transaction-form'],'cancel-bill':['editingBill','bill-form'],'cancel-procedure':['editingProcedure','procedure-form']};
 if(cancel[action]){const [key,formId]=cancel[action];state[key]=null;window.UPForms?.clear(formId);render();return;}
 const deletes={'delete-bill':'kitBills','delete-offer':'personalOffers','delete-procedure':'procedures'};
 if(deletes[action]){if(!confirm('Excluir este registro?'))return;state[deletes[action]]=state[deletes[action]].filter(x=>String(x.id)!==el.dataset.id);save();render();flash('Registro excluído.');return;}
 if(action==='new-offer'){state.offerDraft={};state.editingOffer=null;window.UPForms?.clear('offer-form');render();return;}
 if(action==='profile-tab'){state.profileTab=el.dataset.tab;render();return;}

 if(action==='logout'){if(backend){try{await backend.logout();state=fresh();}catch(error){return flash(error.message);}}state.signed=false;save();navigate('login');return;}
 if(action==='demo-enter'&&!backend){state.signed=true;state.consent=true;save();navigate('dashboard');return;}
 if(action==='diag-next')return navStep(1);
 if(action==='diag-back')return navStep(-1);
 if(action==='fin-next'){if(el.disabled)return;el.disabled=true;try{return await navStep(1);}finally{if(el.isConnected)el.disabled=false;}}
 if(action==='fin-back')return navStep(-1);
 if(action==='print'){window.print();return;}
 if(action==='view-diagnostic'||action==='view-finance'){if(action==='view-diagnostic'){state.selectedDiagnostic=el.dataset.id;navigate('diagnostic-result');}else{state.selectedFinance=el.dataset.id;navigate('finance-result');}save();return;}
 if(action==='history-diag'||action==='history-finance'){state.historyTab=action==='history-diag'?'diag':'finance';save();render();return;}
 if(action==='remove-debt'){captureDraft();state.financeDraft.debts.splice(Number(el.dataset.index),1);save();render();return;}
 if(action==='choose-script'){state.selectedScript=el.dataset.id;save();render();return;}
 if(action==='copy-script'){copyText(scriptText());return;}
 if(action==='whatsapp-script'){window.open('https://wa.me/?text='+encodeURIComponent(scriptText()),'_blank','noopener,noreferrer');return;}
 if(action==='export-csv'){let arr=state.kitTransactions,[...heads]=[['data','descricao','valor','tipo','categoria','escopo']];let rows=arr.map(x=>[x.date,x.desc,x.value,x.type,x.category,x.scope].map(v=>{const value=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(value)?"'":'')+value.replaceAll('"','""')+'"';}).join(';'));downloadFile('up-lancamentos.csv','\ufeff'+heads.join(';')+'\n'+rows.join('\n'),'text/csv;charset=utf-8');return;}
 if(action==='del-transaction'){if(!confirm('Excluir este lançamento?'))return;state.kitTransactions=state.kitTransactions.filter(x=>String(x.id)!==el.dataset.id);save();render();flash('Lançamento excluído.');return;}
 if(action==='toggle-bill'){let x=state.kitBills.find(t=>String(t.id)===el.dataset.id);if(x)x.paid=!x.paid;save();render();return;}
 if(action==='template-offer'){const type=OFFERS[Number(el.dataset.template)]||OFFERS[0];state.offerDraft={name:'Minha oferta · '+type,type};state.editingOffer=null;window.UPForms?.clear('offer-form');save();render();document.querySelector('#offer-form input')?.focus();return;}
 if(action==='export-json'){downloadFile('software-up-meus-dados-demo.json',JSON.stringify({user:state.user,diagnostics:state.diagnostics,finances:state.finances,kitTransactions:state.kitTransactions,kitBills:state.kitBills,personalOffers:state.personalOffers,plan:state.plan,checkins:state.checkins,procedures:state.procedures},null,2),'application/json');return;}
 if(action==='clear-data'&&!backend){if(confirm('Apagar todos os dados locais da demonstração? Esta ação não pode ser desfeita.')){localStorage.removeItem('up-demo-v2');state=fresh();navigate('login');}return;}
}
function newId(){return Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);}
function upsert(list,record){const i=list.findIndex(x=>String(x.id)===String(record.id));if(i<0)list.push(record);else list[i]={...list[i],...record};}
function recordId(form,editing){if(editing)return editing;if(!form.__recordId)form.__recordId=newId();return form.__recordId;}
async function finishForm(form,message,redraw=true,page=''){save();try{if(backend?.flush)await backend.flush();}catch(error){window.UPForms?.feedback(form,error.message,'error');flash(error.message);return false;}window.UPForms?.clear(form.id);if(page)navigate(page);else if(redraw)render();else window.UPForms?.feedback(form,message);flash(message);return true;}
function formData(form){return Object.fromEntries(new FormData(form).entries());}
async function formSubmit(form){if(window.UPForms&&!window.UPForms.validate(form))return;let id=form.id,o=formData(form);
 if(backend&&['login-form','verify-form'].includes(id)){
 const submit=form.querySelector('button[type="submit"]');submit.disabled=true;
 try{if(id==='login-form'){state.codeEmail=(o.email||'').toLowerCase().trim();await backend.request('/auth/request-code',{email:state.codeEmail});navigate('code');}else{await backend.request('/auth/verify-code',{email:state.codeEmail,code:o.code||[0,1,2,3,4,5].map(i=>o['digit'+i]||'').join('')});state=Object.assign(fresh(),await backend.load());normalizeState();navigate('dashboard');}}catch(error){flash(error.message);}finally{submit.disabled=false;}return;
 }

 if(id==='login-form'){state.user.email=(o.email||'').toLowerCase().trim();state.codeEmail=state.user.email;save();navigate('code');return;}
 if(id==='verify-form'){let code=[0,1,2,3,4,5].map(n=>o['digit'+n]).join('');if(code!=='123456')return flash('Na demonstração, use o código 123456.');state.signed=true;state.consent=true;save();navigate('dashboard');return;}
 if(id==='diagnostic-profile'){captureDraft();let d=state.diagnosticDraft;d.gargalo=o.gargalo;d.dificuldade=o.dificuldade;d.dificuldadeTexto=o.dificuldadeTexto;d.perfil={business:o.business,age:o.age,band:o.band,team:o.team};let result;try{result=L.diagnostic(d);}catch(e){return flash(e.message);}const diagId=Date.now();state.selectedDiagnostic=diagId;state.diagnostics.push({id:diagId,created:today(),input:JSON.parse(JSON.stringify(d)),result});state.diagStep=0;state.diagnosticDraft=fresh().diagnosticDraft;return finishForm(form,'Diagnóstico concluído.',false,'diagnostic-result');}
 if(id==='debt-form'){captureDraft();if(!(Number(o.balance)>0)||!(Number(o.payment)>0)||Number(o.rate)<0)return flash('Informe saldo e parcela maiores que zero e juros não negativos.');state.financeDraft.debts.push({id:newId(),creditor:o.creditor,scope:o.scope,balance:o.balance,payment:o.payment,rate:o.rate,overdue:o.overdue==='yes'});return finishForm(form,'Dívida adicionada.');}
 if(id==='transaction-form'){if(!(Number(o.value)>0))return flash('O valor deve ser maior que zero.');upsert(state.kitTransactions,{id:recordId(form,state.editingTransaction),date:o.date,desc:o.desc.trim(),value:Number(o.value),type:o.type,category:o.category,scope:o.scope});state.financeViewMonth=o.date.slice(0,7);state.editingTransaction=null;return finishForm(form,'Lançamento salvo.');}
 if(id==='bill-form'){if(!(Number(o.value)>0))return flash('Informe o valor da conta.');const old=state.kitBills.find(x=>String(x.id)===String(state.editingBill));upsert(state.kitBills,{id:recordId(form,state.editingBill),desc:o.desc.trim(),value:Number(o.value),due:o.due,paid:old?.paid||false});state.editingBill=null;return finishForm(form,'Conta salva.');}
 if(id==='sim-debt'){updateDebtPreview();window.UPForms?.feedback(form,'Simulação atualizada.');return;}
 if(id==='offer-form'){const old=state.offerDraft?null:state.personalOffers.find(x=>String(x.id)===String(state.editingOffer))||state.personalOffers.at(-1);upsert(state.personalOffers,{...o,id:recordId(form,old?.id),saved:today()});state.offerDraft=null;state.editingOffer=null;return finishForm(form,'Oferta salva.');}
 if(id==='plan-form'){if(!o.result?.trim())return window.UPForms?.feedback(form,'Descreva o resultado que você quer alcançar.','error');state.plan={...o};return finishForm(form,'Plano salvo.');}
 if(id==='checkin-form'){if(!o.q1?.trim())return window.UPForms?.feedback(form,'Conte ao menos o que você avançou nesta semana.','error');upsert(state.checkins,{id:recordId(form),date:today(),answers:[o.q1,o.q2,o.q3,o.q4,o.q5]});return finishForm(form,'Check-in salvo.');}
 if(id==='procedure-form'){upsert(state.procedures,{...o,created:today(),id:recordId(form,state.editingProcedure)});state.editingProcedure=null;return finishForm(form,'Procedimento salvo.');}
 if(id==='profile-form'){if(backend){if(backend.flush)await backend.flush();const result=await backend.request('/me',{name:o.name.trim()},'PATCH');state.user=result.user;}else state.user={...state.user,name:o.name.trim(),email:o.email.toLowerCase().trim()};return finishForm(form,'Perfil atualizado.');}
 if(id==='admin-products'&&!backend){state.admin.productIds={front:o.front,essencial:o.essencial,kit:o.kit};return finishForm(form,'Produtos salvos.');}
 if(id==='admin-script'&&!backend){state.messageTemplates.push({id:Date.now(),title:o.title,text:o.text});return finishForm(form,'Modelo adicionado.');}
 if(id==='admin-config'&&!backend){if(o.kitLink&&!/^https:\/\//i.test(o.kitLink))return flash('Utilize uma URL HTTPS válida.');state.admin.kitLink=o.kitLink;return finishForm(form,'Configurações salvas.');}
}
document.addEventListener('click',e=>{const score=e.target.closest('[data-score-group]');if(score){captureDraft();let g=score.dataset.scoreGroup,n=score.dataset.scoreName;state.diagnosticDraft[g][n]=state.diagnosticDraft[g][n]||{};state.diagnosticDraft[g][n].score=Number(score.dataset.scoreValue);const value=score.dataset.scoreValue;save();render();[...document.querySelectorAll('[data-score-group]')].find(b=>b.dataset.scoreGroup===g&&b.dataset.scoreName===n&&b.dataset.scoreValue===value)?.focus({preventScroll:true});return;}
 const tab=e.target.closest('[data-admin-tab]');if(tab){state.adminTab=tab.dataset.adminTab;save();render();return;}
 const nav=e.target.closest('[data-go]');if(nav){captureDraft();navigate(nav.dataset.go);return;}
 const act=e.target.closest('[data-action]');if(act){Promise.resolve(doAction(act)).catch(error=>flash(error.message||'Não foi possível concluir. Tente novamente.'));return;}
});
document.addEventListener('submit',async e=>{const form=e.target;if(!form?.id)return;e.preventDefault();const submit=form.querySelector('button[type="submit"]');if(submit?.disabled)return;if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true');}try{await formSubmit(form);}catch(error){window.UPForms?.feedback(form,error.message||'Não foi possível salvar. Tente novamente.','error');flash(error.message||'Confira os dados e tente novamente.');}finally{if(submit){submit.disabled=false;submit.removeAttribute('aria-busy');}}});
document.addEventListener('input',changeTarget);
document.addEventListener('change',changeTarget);
document.addEventListener('paste',e=>{if(!e.target.matches('.code-fields input'))return;const digits=e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);if(!digits)return;e.preventDefault();const fields=[...e.target.parentElement.querySelectorAll('input')];digits.split('').forEach((digit,i)=>{if(fields[i])fields[i].value=digit;});fields[Math.min(digits.length,5)]?.focus();});
document.addEventListener('keydown',e=>{if(e.target.matches('.code-fields input')&&e.key==='Backspace'&&!e.target.value)e.target.previousElementSibling?.focus();});
document.addEventListener('keydown',e=>{if(e.target.matches('.code-fields input')&&e.key.length===1&&/\d/.test(e.key)){setTimeout(()=>e.target.nextElementSibling?.focus(),0);}});
if(backend){window.addEventListener('up-sync',event=>{const status=$('#sync-status');if(status)status.textContent=event.detail.message;if(event.detail.error)flash(event.detail.message);});backend.load().then(data=>{state=Object.assign(fresh(),data);normalizeState();}).catch(error=>{state=fresh();if(error.status!==401)flash('Não foi possível carregar a conta. Tente entrar novamente.');}).finally(()=>{loading=false;render();});}
render();
})();
